<?php
require_once __DIR__.'/../configuracion/admin-ui.php';require_once __DIR__.'/../configuracion/autentifica_admin.php';
$queries=app_rows('SELECT id_consulta,nombre_consulta FROM consultas_email ORDER BY id_consulta DESC');
$id=(int)app_value($_GET,'id_consulta',$queries?(int)$queries[0]['id_consulta']:0);$q=trim(app_value($_GET,'q'));$answer=app_value($_GET,'respuesta');$page=max(1,(int)app_value($_GET,'pagina',1));$size=50;
$selected=app_rows('SELECT id_consulta,nombre_consulta,pregunta_consulta,CAST(opciones AS BINARY) AS opciones FROM consultas_email WHERE id_consulta=?','i',array($id));$selected=$selected?$selected[0]:array('nombre_consulta'=>'Sin consultas','pregunta_consulta'=>'','opciones'=>'');
$options=$selected['opciones']?security_unserialize($selected['opciones']):array();if(!is_array($options))$options=array();
$sql='WITH ranked AS (SELECT r.id,r.fecha,r.opcion_seleccionada,r.id_alumno,a.id_usuario,a.nivel_actual,a.nivel_proximo,ROW_NUMBER() OVER(PARTITION BY a.id_usuario ORDER BY r.fecha DESC,r.id DESC) AS rn FROM consultas_email_respuestas r JOIN alumnos a ON a.id_alumno=r.id_alumno WHERE r.id_consulta=? AND a.id_centro=?) SELECT r.*,u.Nombre,u.Apellido1,u.Apellido2,u.fecha_nacimiento,u.nonato FROM ranked r JOIN usuarios u ON u.id_usuario=r.id_usuario WHERE r.rn=1 ORDER BY r.fecha DESC,r.id DESC';
$all=app_rows($sql,'ii',array($id,(int)$centro_actual));$summary=array();foreach($all as $r)$summary[$r['opcion_seleccionada']]=($summary[$r['opcion_seleccionada']]??0)+1;
$fold=function($s){return mb_strtolower(app_text($s),'UTF-8');};
$filtered=array_values(array_filter($all,function($r)use($q,$answer,$fold){return ($answer===''||(string)$r['opcion_seleccionada']===$answer)&&($q===''||mb_strpos($fold($r['Nombre'].' '.$r['Apellido1'].' '.$r['Apellido2']),$fold($q))!==false);}));
$total=count($filtered);$page=min($page,max(1,(int)ceil($total/$size)));$rows=array_slice($filtered,($page-1)*$size,$size);$history=array();$groups=array();
if($rows){
 $students=array_values(array_unique(array_map(fn($r)=>(int)$r['id_usuario'],$rows)));$marks=implode(',',array_fill(0,count($students),'?'));
 foreach(app_rows('SELECT r.*,a.id_usuario FROM consultas_email_respuestas r JOIN alumnos a ON a.id_alumno=r.id_alumno WHERE r.id_consulta=? AND a.id_centro=? AND a.id_usuario IN ('.$marks.') ORDER BY r.fecha DESC,r.id DESC','ii'.str_repeat('i',count($students)),array_merge(array($id,(int)$centro_actual),$students)) as $r)$history[$r['id_usuario']][]=$r;
 $enrolments=array_values(array_unique(array_map(fn($r)=>(int)$r['id_alumno'],$rows)));$marks=implode(',',array_fill(0,count($enrolments),'?'));
 foreach(app_rows('SELECT DISTINCT ag.id_alumno,g.dia,g.hora_inicio,g.hora_fin FROM aulas_alumnos_grupos ag JOIN aulas_grupos g ON g.id_grupo=ag.id_grupo WHERE ag.id_alumno IN ('.$marks.') ORDER BY g.dia,g.hora_inicio',str_repeat('i',count($enrolments)),$enrolments) as $r)$groups[$r['id_alumno']][]=$r;
}
$days=array(1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo');
neo_page_start('Respuestas de las familias','Revisa la última respuesta de cada alumno y despliega su historial cuando lo necesites.','Consultas y formularios');
?>
<section class="neo-panel"><form method="get" class="neo-filters"><label class="grow">Consulta<select name="id_consulta"><?php foreach($queries as $item){ ?><option value="<?=(int)$item['id_consulta']?>" <?=((int)$item['id_consulta']===$id?'selected':'')?>><?=app_escape($item['nombre_consulta'])?></option><?php } ?></select></label><label>Alumno<input type="search" name="q" value="<?=app_escape($q)?>" placeholder="Nombre o apellidos"></label><label>Respuesta<select name="respuesta"><option value="">Todas las respuestas</option><?php foreach($options as $key=>$label){if(!is_scalar($label))continue; ?><option value="<?=app_escape($key)?>" <?=((string)$key===$answer?'selected':'')?>><?=app_escape($label)?></option><?php } ?></select></label><button>Aplicar filtros</button></form></section>
<section class="neo-panel"><h2><?=app_escape($selected['nombre_consulta'])?></h2><p><?=app_escape(strip_tags($selected['pregunta_consulta']))?></p></section><div class="neo-stats"><div class="neo-stat"><strong><?=count($all)?></strong><span>Alumnos que han respondido</span></div><?php foreach($options as $key=>$label){if(!is_scalar($label))continue; ?><div class="neo-stat"><strong><?=(int)($summary[$key]??0)?></strong><span><?=app_escape($label)?></span></div><?php } ?></div>
<div class="neo-table-wrap"><table class="neo-data-table"><thead><tr><th>Alumno</th><th>Nivel</th><th>Grupos</th><th>Nacimiento</th><th>Última respuesta</th><th>Historial</th><th>Ficha</th></tr></thead><tbody>
<?php foreach($rows as $r){$level=(int)$r['nivel_proximo'];if(!$level&&(int)$r['nivel_actual'])$level=(int)$r['nivel_actual']*3-2; ?><tr><td><strong><?=app_escape(trim($r['Nombre'].' '.$r['Apellido1'].' '.$r['Apellido2']))?></strong><small>#<?=(int)$r['id_usuario']?></small></td><td><span class="neo-pill"><?=app_escape($nombres_subniveles[$level]??'Pendiente')?></span></td><td><?php foreach($groups[$r['id_alumno']]??array() as $g){ ?><small><?=app_escape(($days[$g['dia']]??'').' '.substr($g['hora_inicio'],0,5).'–'.substr($g['hora_fin'],0,5))?></small><?php } if(empty($groups[$r['id_alumno']]))echo '<span class="neo-muted">Sin grupo</span>'; ?></td><td class="nowrap"><?=$r['nonato']?'Pendiente de nacimiento':neo_date($r['fecha_nacimiento'])?></td><td><strong><?=app_escape($options[$r['opcion_seleccionada']]??'Opción '.$r['opcion_seleccionada'])?></strong><small><?=neo_date($r['fecha'],true)?></small></td><td><details><summary><?=count($history[$r['id_usuario']]??array())?> respuestas</summary><?php foreach($history[$r['id_usuario']]??array() as $h){ ?><p><small><?=neo_date($h['fecha'],true)?></small><?=app_escape($options[$h['opcion_seleccionada']]??'Opción '.$h['opcion_seleccionada'])?></p><?php } ?></details></td><td><a class="neo-button secondary" href="/alumnos/nuevo_alumno4.php?u=<?=(int)$r['id_usuario']?>">Ver alumno</a></td></tr><?php } ?>
<?php if(!$rows){ ?><tr><td colspan="7" class="neo-empty">No hay respuestas para estos filtros.</td></tr><?php } ?></tbody></table></div><p class="neo-help">El resumen cuenta la última respuesta de cada alumno, sin duplicarlo si respondió varias veces.</p>
<?php neo_pagination($total,$page,$size);neo_page_end();
